"""Copy reviewed Flutter sources into a disposable CI scaffold, never the reverse."""
from pathlib import Path
import shutil
root = Path(__file__).resolve().parent.parent
project = root / '.codemagic-ios'
if not (project / 'ios' / 'Runner.xcodeproj').is_dir():
    raise SystemExit('Generate the isolated iOS scaffold before copying sources.')
# Remove only the exact example test generated by Flutter, before copying our tests.
example_test = project / 'test' / 'widget_test.dart'
if example_test.exists():
    example_test.unlink()
for folder in ('lib', 'test', 'assets'):
    shutil.copytree(root / folder, project / folder, dirs_exist_ok=True)
shutil.copy2(root / 'pubspec.yaml', project / 'pubspec.yaml')
print('Copied AURYA sources into the isolated CI project. Widget integration remains pending.')
